 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Nonzero runs on the top/bottom borders are the reference strings.
    motifs = []
    for r in {0, h - 1}:
        c = 0
        while c < w:
            if g[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and g[r][c] != 0:
                c += 1
            motifs.append(g[r][start:c])

    # A lone colored marker reproduces its reference string, aligned so
    # that the marker's color lands in its original cell.
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == 0:
                continue
            if r in (0, h - 1):
                continue
            motif = next((m for m in motifs if color in m), None)
            if motif is None:
                continue
            start = c - motif.index(color)
            for i, value in enumerate(motif):
                x = start + i
                if 0 <= x < w:
                    g[r][x] = value
    return g
